using ZoneInfoSourceFactory =
    std::unique_ptr<cctz::ZoneInfoSource> (*)(
        const std::string&,
        const std::function<std::unique_ptr<cctz::ZoneInfoSource>(
            const std::string&)>&);

// ...
extern ZoneInfoSourceFactory zone_info_source_factory;

}  // namespace cctz_extension

